```ts
import { canonicalEventJson } from "@/lib/ledger/hash";

/**
 * Offline capture crypto for the faculty device queue (spec §13+§20).
 *
 * Contract: before going offline, the faculty client calls
 * `mintOfflineBundle(actorToken, sessionId)` and stores the returned
 * {sessionId, key}. While disconnected it queues one record per attested
 * student, signs each with `signRecord(key, record)`, and keeps them in local
 * storage. On reconnect it calls `syncOfflineBatch(actorToken, records)` with
 * the signed records; the server re-verifies every HMAC against the key it
 * stored at mint time, dedupes replays via `nonceHash`, and appends each
 * accepted record to the same attendance ledger seam used by online check-in
 * (origin "offline-faculty"). The record's capturedAt is device-clock
 * evidence only; server time stays authoritative.
 */

export type OfflineBundle = {
  sessionId: string;
  key: string;
};

/** Device-side queued attendance claim; capturedAt is display-only device clock. */
export type OfflineRecord = {
  sessionId: string;
  sectionId: string;
  studentId: string;
  capturedAt: number;
  nonce: string;
  note?: string;
};

export type SignedOfflineRecord = OfflineRecord & { signature: string };

const BUNDLE_KEY_BYTES = 32;

function bytesToHex(bytes: Uint8Array): string {
  let hex = "";
  for (const byte of bytes) {
    hex += byte.toString(16).padStart(2, "0");
  }
  return hex;
}

function hexToBytes(hex: string): Uint8Array {
  if (hex.length % 2 !== 0 || /[^0-9a-f]/i.test(hex)) {
    throw new Error("malformed hex string");
  }
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < bytes.length; i += 1) {
    bytes[i] = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  return bytes;
}

async function hmacSha256Hex(key: string, payload: string): Promise<string> {
  const cryptoKey = await crypto.subtle.importKey(
    "raw",
    hexToBytes(key),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const mac = new Uint8Array(
    await crypto.subtle.sign("HMAC", cryptoKey, new TextEncoder().encode(payload)),
  );
  return bytesToHex(mac);
}

/** 32 random bytes as hex — the per-session pre-authorization secret. */
export function mintBundleKey(): string {
  return bytesToHex(crypto.getRandomValues(new Uint8Array(BUNDLE_KEY_BYTES)));
}

/** HMAC-SHA256 over the canonical JSON of the record fields (hex digest). */
export async function signRecord(key: string, record: OfflineRecord): Promise<SignedOfflineRecord> {
  const signature = await hmacSha256Hex(key, canonicalEventJson({ ...record }));
  return { ...record, signature };
}

function timingSafeEqual(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) return false;
  let difference = 0;
  for (let i = 0; i < a.length; i += 1) {
    difference |= a[i] ^ b[i];
  }
  return difference === 0;
}

/** Recomputes the HMAC over the received fields and compares in constant time. */
export async function verifySignature(key: string, signed: SignedOfflineRecord): Promise<boolean> {
  const { signature, ...record } = signed;
  let expected: string;
  try {
    expected = await hmacSha256Hex(key, canonicalEventJson(record));
  } catch {
    return false;
  }
  try {
    return timingSafeEqual(hexToBytes(expected), hexToBytes(signature));
  } catch {
    return false;
  }
}
```

Hmm wait — verifySignature destructures `signature` then uses it. TS: `{ signature, ...record }` — fine. But canonicalEventJson(record) where record lacks signature — good.

Note about "double-HMAC trick": my XOR-fold compare mirrors existing signer.ts timingSafeEqual — consistent with codebase. Good enough ("prefer timingSafeEqual-style...only if trivially pure" — this is trivially pure).

